export function builtIns(): IBuiltIns {
  const out: IBuiltIns = {
    providers: [],
    extractors: [],
    analyzers: [],
    formatters: [],
    actions: [],
    hooks: [],
  };
  for (const plugin of builtInPlugins) {
    for (const ext of plugin.extensions) {
      bucketBuiltIn(ext, out);
    }
  }
  return out;
}

export function listBuiltIns(): IExtension[] {
  const out: IExtension[] = [];
  for (const plugin of builtInPlugins) {
    for (const x of plugin.extensions) {
      out.push(toExtensionRow(x));
    }
  }
  return out;
}

function bucketBuiltIn(ext: TBuiltInExtension, out: IBuiltIns): void {
  bucketByKind(ext.kind, ext, {
    provider: out.providers,
    extractor: out.extractors,
    analyzer: out.analyzers,
    formatter: out.formatters,
    action: out.actions,
    hook: out.hooks,
  });
}

function toExtensionRow(x: TBuiltInExtension): IExtension {
  const row: IExtension = {
    id: x.id,
    pluginId: x.pluginId,
    kind: x.kind,
    version: x.version,
    description: x.description ?? '',
  };
  return row;
}
